operations.content:
/* Frame Helm -- Foundry sidebar presentation */
#sidebar .frame-conn-sidebar-tab-button i { pointer-events: none; }
#sidebar .frame-conn-sidebar-surface { height: 100%; min-height: 0; overflow: hidden; color: var(--fc-text); background: var(--fc-bg-deep); }
#sidebar .frame-conn-sidebar-scroll { height: 100%; min-height: 0; overflow-x: hidden; overflow-y: auto; scrollbar-gutter: stable; }
#sidebar .frame-conn-sidebar-shell { min-width: 0; width: 100%; padding: 0.4rem; }
#sidebar .frame-conn-sidebar-shell .frame-conn-mech-stats-bar { width: 100%; min-width: 0; }
#sidebar .frame-conn-sidebar-shell .frame-conn-mech-stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.3rem; }
#sidebar .frame-conn-sidebar-shell .frame-conn-stat-cell { min-width: 0; }
#sidebar .frame-conn-sidebar-unit, #sidebar .frame-conn-sidebar-budget, #sidebar .frame-conn-sidebar-actions, #sidebar .frame-conn-sidebar-plan { width: 100%; min-width: 0; margin-top: 0.45rem; }
#sidebar .frame-conn-sidebar-shell .frame-conn-budget-grid, #sidebar .frame-conn-sidebar-shell .frame-conn-action-category-grid, #sidebar .frame-conn-sidebar-shell .frame-conn-action-grid { grid-template-columns: 1fr; }
#sidebar .frame-conn-sidebar-shell button, #sidebar .frame-conn-sidebar-shell input, #sidebar .frame-conn-sidebar-shell select { max-width: 100%; }
#sidebar .frame-conn-sidebar-actions, #sidebar .frame-conn-sidebar-plan { border-top: 1px solid var(--fc-cyan-muted); padding-top: 0.45rem; }
#sidebar .frame-conn-sidebar-plan { padding-bottom: 0.75rem; }
